insert into ticket_types (
    title,
    description,
    currency,
    total_quantity,
    sold_quantity,
    is_active,
    image_asset_id
)
select
    cs.title,
    cs.description,
    cs.currency,
    cs.total_quantity,
    cs.sold_quantity,
    cs.is_active,
    ia.id
from characters_source cs
         join image_assets ia on ia.external_id = cs.external_id
on conflict do nothing;

