),
     ticket_types as (
         select
             t.id as ticket_type_id,
             t.title as type_title,
             t.description as type_description,
             cs.slug as type_slug,
             cs.price as base_price,
             t.currency,
             t.is_active,
             t.image_asset_id
         from ticket_types t
                  join image_assets ia on ia.id = t.image_asset_id
                  join characters_source cs on cs.external_id = ia.external_id
     ),
     expanded as (
         select
             tt.*,
             gs.instance_no,
             (
                 timestamptz '2100-01-01 00:00:00+00'
                     + make_interval(
                         days => (abs(hashtext(tt.type_slug || '-day-' || gs.instance_no::text)) % 36525),
                         mins => (abs(hashtext(tt.type_slug || '-min-' || gs.instance_no::text)) % 1440)
                       )
                 ) as event_at
         from ticket_types tt
                  cross join lateral generate_series(
                 1,
                 2 + (abs(hashtext(tt.type_slug || '-instances')) % 4)
                                     ) as gs(instance_no)
     ),
     prepared as (
         select
             concat(
                     ex.type_slug,
                     '-event-',
                     to_char(ex.event_at at time zone 'UTC', 'YYYYMMDDHH24MI'),
                     '-',
                     ex.instance_no
             ) as slug,
             concat(ex.type_title, ' Live #', ex.instance_no) as title,
             concat(
                     ex.type_description,
                     ' Doors open at ',
                     to_char(ex.event_at at time zone 'UTC', 'FMMonth DD, YYYY "at" HH24:MI "UTC"'),
                     '.'
             ) as description,
             greatest(
                     290,
                     ex.base_price
                         + ((abs(hashtext(ex.type_slug || '-price-' || ex.instance_no::text)) % 701) - 250)
             )::integer as price,
             ex.currency,
             (20 + (abs(hashtext(ex.type_slug || '-qty-' || ex.instance_no::text)) % 81))::integer as total_quantity,
             ex.is_active,
             ex.image_asset_id,
             ex.ticket_type_id,
             ex.event_at
         from expanded ex
     )
insert into ticket_events (
    ticket_type_id,
    slug,
    title,
    description,
    event_at,
    price,
    currency,
    total_quantity,
    sold_quantity,
    is_active,
    image_asset_id
)
select
    p.ticket_type_id,
    p.slug,
    p.title,
    p.description,
    p.event_at,
    p.price,
    p.currency,
    p.total_quantity,
    (abs(hashtext(p.slug || '-sold')) % (p.total_quantity + 1))::integer as sold_quantity,
    p.is_active,
    p.image_asset_id
from prepared p
on conflict (slug) do update
    set
        ticket_type_id = excluded.ticket_type_id,
        title = excluded.title,
        description = excluded.description,
        event_at = excluded.event_at,
        price = excluded.price,
        currency = excluded.currency,
        total_quantity = excluded.total_quantity,
        sold_quantity = excluded.sold_quantity,
        is_active = excluded.is_active,
        image_asset_id = excluded.image_asset_id,
        updated_at = now();
